@property
def port(self):
    port = self._hostinfo[1]
    if port is not None:
        if port.isdigit() and port.isascii():
            port = int(port)
        else:
            raise ValueError(f"Port could not be cast to integer value as {port!r}")
        if not (0 <= port <= 65535):
            raise ValueError("Port out of range 0-65535")
    return port

